  "qa": [
    {
      "question": "学校在学生退学情况下，学费和住宿费的退费政策是什么？",
      "answer": "学生退学后，学费和住宿费按比例退费，其中书费不予退还，住宿费退一半，因学生已使用半年住宿资源。"
    },
    {
      "question": "学校如何利用节省的水电费用提升教学质量？",
      "answer": "学校通过减少水电支出，将节省的经费用于提升教学质量，例如支持教师开展项目研究。"
    },
    {
      "question": "学校为教师提供哪些福利或补贴？",
      "answer": "学校在节日期间向教师发放月饼、粽子等节日礼品，并通过节省的水电费用为教师提供额外支持。"
    }
  ]
}
